<article class="story-card"><a class="story-image" href="<?= e(url('news/'.$story['slug'])) ?>"><img src="<?= e(media_url($story['image_path'] ?? null)) ?>" alt="<?= e(localized($story,'title')) ?>" loading="lazy" width="640" height="400"><?php if (!empty($story['video_url']) || !empty($story['video_media_id'])): ?><span class="play-label">▶ Video</span><?php endif ?></a><div class="story-copy"><div class="story-kicker"><span class="category-badge badge-<?= e($story['category_slug'] ?? '') ?>"><?= e($story['category_name'] ?: 'News') ?></span><time datetime="<?= e(date('c',strtotime($story['published_at']))) ?>"><?= e(date('d M · H:i',strtotime($story['published_at']))) ?></time></div><h3><a href="<?= e(url('news/'.$story['slug'])) ?>"><?= e(localized($story,'title')) ?></a></h3><p><?= e(localized($story,'summary')) ?></p><div class="story-bottom"><span><?= e($story['author_name'] ?? '') ?></span><a href="<?= e(url('news/'.$story['slug'])) ?>"><?= e(t('Read story')) ?> →</a></div></div></article>
